	@Test
	void fallsBackToDirectChildWhenProcessTreeInspectionIsUnavailable() throws Exception {
		InspectionDeniedProcess process = new InspectionDeniedProcess();

		WorkerLauncher.WorkerProcess worker = JavaProcessWorkerLauncher.wrap(process);

		assertTrue(worker.waitFor(Duration.ofSeconds(1)));
		assertTrue(process.directWaitInvoked);
		assertEquals("direct-child", worker.terminationScope());
		assertFalse(worker.isAlive());
		worker.destroy();
		assertTrue(process.destroyInvoked);
	}

	@Test
	void launchesDirectCliAndPreservesFailureAndTimeoutArtifacts() throws Exception {
		Path directory = Files.createTempDirectory("rdf4j-java-worker-launcher-");
		try {
			JavaProcessWorkerLauncher launcher = new JavaProcessWorkerLauncher();

			Path helpStdout = directory.resolve("help.stdout.log");
			Path helpStderr = directory.resolve("help.stderr.log");
			WorkerLauncher.WorkerProcess help = launcher.launch(List.of("--help"), helpStdout, helpStderr);
			assertTrue(help.waitFor(Duration.ofSeconds(30)));
			assertEquals(0, help.exitValue());
			assertTrue(Files.readString(helpStdout, StandardCharsets.UTF_8).contains("Query plan snapshot CLI"));

			Path failureStdout = directory.resolve("failure.stdout.log");
			Path failureStderr = directory.resolve("failure.stderr.log");
			WorkerLauncher.WorkerProcess failure = launcher.launch(List.of("--not-a-real-option"), failureStdout,
					failureStderr);
			assertTrue(failure.waitFor(Duration.ofSeconds(30)));
			assertNotEquals(0, failure.exitValue());
			assertTrue(Files.readString(failureStderr, StandardCharsets.UTF_8)
					.contains("Unknown argument: --not-a-real-option"));

			Path timeoutAudit = directory.resolve("timeout-audit.csv");
			QueryPlanSnapshotBatchProcessRunner runner = new QueryPlanSnapshotBatchProcessRunner(
					launcher,
					Duration.ofMillis(10),
					Duration.ofSeconds(2),
					timeoutAudit,
					directory.resolve("timeout-artifacts"),
					new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8));
			QueryPlanSnapshotBatchProcessRunner.WorkerTarget target = new QueryPlanSnapshotBatchProcessRunner.WorkerTarget(
					"memory-preflight-timeout", "ALL", -1,
					List.of("--no-interactive", "--store", "memory", "--batch-data-preflight"));
			QueryPlanSnapshotBatchProcessRunner.Summary summary = runner.run(null, List.of(target), null);

			assertEquals(1, summary.attempted());
			assertEquals(1, summary.timedOut());
			String audit = Files.readString(timeoutAudit, StandardCharsets.UTF_8);
			assertTrue(audit.contains("memory-preflight-timeout,ALL,-1,timed_out,"), audit);
			assertTrue(Files.isRegularFile(directory.resolve("timeout-artifacts/memory-preflight-timeout.stdout.log")));
			assertTrue(Files.isRegularFile(directory.resolve("timeout-artifacts/memory-preflight-timeout.stderr.log")));
			assertFalse(audit.contains("forcible-still-alive"), audit);
		} finally {
			FileUtil.deleteDir(directory.toFile());
		}
	}

	@Test
	void isolatedCliWorkerPreservesParentLmdbConfigurationDefaults() throws Exception {
		Path directory = Files.createTempDirectory("rdf4j-java-worker-config-");
		try {
			Path dataDirectory = Files.createDirectories(directory.resolve("lmdb/triples"));
			Files.writeString(dataDirectory.resolve("data.mdb"), "fixture-bytes");
			Path manifest = directory.resolve("fixture-manifest.json");
			List<String> arguments = List.of(
					"--no-interactive",
					"--store", "lmdb",
					"--lmdb-data-dir", directory.resolve("lmdb").toString(),
					"--lmdb-store-manifest", manifest.toString(),
					"--lmdb-evidence-mode", "snapshot-only",
					"--write-lmdb-store-manifest");
			QueryPlanSnapshotCliOptions parentOptions = QueryPlanSnapshotCli
					.parseArgs(arguments.toArray(String[]::new));

			JavaProcessWorkerLauncher launcher = new JavaProcessWorkerLauncher();
			WorkerLauncher.WorkerProcess worker = launcher.launch(arguments, directory.resolve("worker.stdout.log"),
					directory.resolve("worker.stderr.log"));

			assertTrue(worker.waitFor(Duration.ofSeconds(30)));
			assertEquals(0, worker.exitValue());
			assertDoesNotThrow(() -> QueryPlanSnapshotStoreSupport.readLmdbStoreManifestHeader(manifest,
					QueryPlanSnapshotStoreSupport.createLmdbStoreConfig(parentOptions)));
		} finally {
			FileUtil.deleteDir(directory.toFile());
		}
	}

	@Test
	void doesNotReportSuccessWhileDiscoveredDescendantIsAlive() throws Exception {
		String javaExecutable = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		String classpath = JavaProcessWorkerLauncher.resolveClasspath();
		Process parent = new ProcessBuilder(javaExecutable, "-cp", classpath,
				ParentThatSpawnsDescendant.class.getName(), javaExecutable, classpath,
				LongLivedDescendant.class.getName()).start();
		WorkerLauncher.WorkerProcess worker = JavaProcessWorkerLauncher.wrap(parent);
		try {
			assertFalse(worker.waitFor(Duration.ofMillis(500)),
					"A completed parent must not hide a still-running descendant.");
			worker.destroy();
			if (!worker.waitFor(Duration.ofSeconds(2))) {
				worker.destroyForcibly();
			}
			assertTrue(worker.waitFor(Duration.ofSeconds(2)));
			assertFalse(worker.isAlive());
		} finally {
			if (worker.isAlive()) {
				worker.destroyForcibly();
			}
		}
	}

	@Test
	void retainsDiscoveredDescendantsWhenLaterInspectionFails() throws Exception {
		LateInspectionFailureProcess process = new LateInspectionFailureProcess();
		WorkerLauncher.WorkerProcess worker = JavaProcessWorkerLauncher.wrap(process);

		assertFalse(worker.waitFor(Duration.ofMillis(25)),
				"A later inspection failure must not discard an already-discovered live descendant.");
		assertEquals("known-process-tree", worker.terminationScope());
		worker.destroyForcibly();
		assertTrue(process.descendant.forciblyDestroyed);
	}

